mapper.select:
select borrowId, borrow.userId, borrow.bookId, borrowTime, returnTime, dueDate, isOverdue, overdueDays, fine, renewCount, lastRenewTime, userName, bookName from borrow, user, book_info where borrow.userId = user.userId and borrow.bookId = book_info.bookId
and userName like concat('%',#{username},'%')
and bookName like concat('%',#{bookname},'%')
and borrow.userId = #{userid}
limit #{begin}, #{size}

select borrowId, userId, bookId, borrowTime, returnTime, dueDate, isOverdue, overdueDays, fine,
       (select userName from user where borrow.userId = user.userId) userName,
       (select bookName from book_info where borrow.bookId = book_info.bookId) bookName
from borrow
where userId = #{userid}
limit #{begin}, #{size}

mapper.update:
update borrow
set renewCount = #{renewcount,jdbcType=INTEGER},
    dueDate = #{duedate,jdbcType=TIMESTAMP},
    lastRenewTime = #{lastrenewwtime,jdbcType=TIMESTAMP}
where borrowId = #{borrowid,jdbcType=INTEGER}
